    simp +decide [ Fintype.piFinset ];
    gcongr ; norm_num;
  exact_mod_cast h_card_le_mul_card_image.trans ( Nat.mul_le_mul_left _ ( Finset.card_le_card h_image_subset_T |> le_trans <| h_card_T ) ) |> le_trans <| by ring_nf; norm_num;

:= by
  refine' ⟨ _, _ ⟩;
