  · refine' ⟨ Polynomial.X ^ 2 - Polynomial.C ( q3 k : ℤ ), _, _ ⟩;
    · erw [ Polynomial.Monic, Polynomial.leadingCoeff_X_pow_sub_C ] ; norm_num;
