:= by
  by_cases hnone : none ∈ U <;> simp_all +decide [ IsSquare ];
  · have h_prod_pos : 0 < ∏ k ∈ U.erase none, (mqSq g k : ℚ) := by
      refine' Finset.prod_pos fun k hk => _;
      cases k <;> simp_all +decide [ mqSq ];
