        · simp +zetaDelta at *;
          intro a ha; cases a <;> simp_all +decide [ q3_spec ] ;
        · rw [ Finset.prod_image ];
          intro x hx y hy; cases x <;> cases y <;> simp_all +decide [ q3_strictMono.injective.eq_iff ] ;
